-- Romanian Zip Codes Database
-- Actualized for May 31, 2026
-- Sourced from GeoNames (http://download.geonames.org/export/zip/)
-- License: Creative Commons Attribution 4.0 License

CREATE TABLE IF NOT EXISTS romanian_zip_codes (
    postal_code CHAR(6) NOT NULL,
    place_name VARCHAR(180) NOT NULL,
    county VARCHAR(100) NOT NULL,
    county_code VARCHAR(5) NOT NULL,
    municipality VARCHAR(100),
    latitude DECIMAL(9, 6),
    longitude DECIMAL(9, 6),
    PRIMARY KEY (postal_code, place_name, county)
);

-- Indexes for performance
CREATE INDEX IF NOT EXISTS idx_postal_code ON romanian_zip_codes (postal_code);
CREATE INDEX IF NOT EXISTS idx_county ON romanian_zip_codes (county);

BEGIN TRANSACTION;


COMMIT;
